Action.ExecScriptExpression:
using System;
using System.Linq;
using System.Text;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.FFXIV;
using Triggernometry.Utilities;

static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

var offset = 0x3800;
var maxlevel = 20;
var stars = 15;
var allEntities = Triggernometry.FFXIV.Entity.GetEntities().Where(e => e.BNpcID == 0);
int totalCount = allEntities.Count();

var output1Builder = new StringBuilder();
var output2Builder = new StringBuilder();

foreach(var entity in allEntities)
{
    IntPtr finalAddress = (IntPtr)entity.Address + offset;
    Status status = entity.Statuses.FirstOrDefault(s => s.StatusID == 4226);
    var level = Memory.Read<byte>(Memory.XivProcHandle, finalAddress);
    
    if(level < maxlevel)
    {
        output1Builder.Append($"{entity.Name}({level}级),");
    }
    
    int stackCount = status?.Stack ?? 0;
    if(stackCount < stars)
    {
        output2Builder.Append($"{entity.Name}({stackCount}星),");
    }
}

string output1 = output1Builder.Length == 0 
    ? "所有人都是满级" 
    : "没满级的是：" + output1Builder.ToString().TrimEnd(',');

string output2 = output2Builder.Length == 0 
    ? "所有人都是满星" 
    : "没满星的是：" + output2Builder.ToString().TrimEnd(',');

var output = $"附近人数：{totalCount}人\n{output1}\n{output2}";
Log(output);

using System;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Utilities;
using Triggernometry.FFXIV;

static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

// 状态ID常量
const int STATUS_FREE_MAN = 4242;
const int STATUS_MONK = 4360;
const int STATUS_PROPHET = 4368;

// 需要拼接名字的状态ID及其对应Builder
var nameBuilders = new Dictionary<int, StringBuilder>
{
    { STATUS_FREE_MAN, new StringBuilder() },
    { STATUS_MONK, new StringBuilder() },
    { STATUS_PROPHET, new StringBuilder() }
};

// 状态中文名映射
var statusNames = new Dictionary<int, string>
{
    { 4358, "骑士" }, { 4359, "狂战士" }, { 4361, "猎人" }, { 4362, "武士" },
    { 4363, "吟游诗人" }, { 4364, "风水师" }, { 4365, "时魔法师" }, { 4366, "炮击士" },
    { 4367, "药剂师" }, { 4369, "盗贼" },
    { 4803, "魔法剑士" }, { 4804, "剑斗士" }, { 4805, "舞者" }
};

// 只需计数的状态ID列表
var simpleCountStatuses = new[] { 4358, 4359, 4361, 4362, 4363, 4364, 4365, 4366, 4369, 4803, 4804, 4805 };

// 计数器初始化
var counts = simpleCountStatuses.ToDictionary(id => id, _ => 0);
int count4367Total = 0;
int count4367NonHealer = 0;

// 获取所有玩家实体
var allEntities = Triggernometry.FFXIV.Entity.GetEntities()
    .Where(e => e.BNpcID == 0 && e.Statuses != null)
    .ToList();

// 处理每个实体的状态
foreach (var entity in allEntities)
{
    foreach (var status in entity.Statuses)
    {
        int statusId = status.StatusID;
        
        // 拼接名字类型
        if (nameBuilders.TryGetValue(statusId, out var sb))
        {
            sb.Append(entity.Name).Append(",");
            continue;
        }
        
        // 药剂师特殊处理
        if (statusId == 4367)
        {
            count4367Total++;
            if (!entity.Job.IsHealer) count4367NonHealer++;
            continue;
        }
        
        // 简单计数类型
        if (counts.ContainsKey(statusId))
        {
            counts[statusId]++;
        }
    }
}

// 生成输出
string GetNameOutput(int statusId, StringBuilder sb, string label)
{
    return sb.Length == 0 ? $"未发现辅助{label}" : $"辅助{label}是：{sb.ToString().TrimEnd(',')}";
}

var output = new StringBuilder()
    .AppendLine($"附近人数：{allEntities.Count}人")
    .AppendLine(GetNameOutput(STATUS_FREE_MAN, nameBuilders[STATUS_FREE_MAN], "自由人"))
    .AppendLine(GetNameOutput(STATUS_MONK, nameBuilders[STATUS_MONK], "武僧"))
    .AppendLine(GetNameOutput(STATUS_PROPHET, nameBuilders[STATUS_PROPHET], "预言师"))
    .AppendLine($"辅助盗贼{counts[4369]}人，辅助猎人{counts[4361]}人，辅助时魔法师{counts[4365]}人")
    .AppendLine($"辅助骑士{counts[4358]}人，辅助吟游诗人{counts[4363]}人，辅助武士{counts[4362]}人")
    .AppendLine($"辅助狂战士{counts[4359]}人，辅助风水师{counts[4364]}人，辅助炮击士{counts[4366]}人")
    .AppendLine($"辅助魔法剑士{counts[4803]}人，辅助剑斗士{counts[4804]}人，辅助舞者{counts[4805]}人")
    .Append($"辅助药剂师{count4367Total}人（火种{count4367NonHealer}人）")
    .ToString();

Log(output);

using System;
using System.Text;
using System.Linq;
using System.Collections.Generic;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.Utilities;
using Triggernometry.FFXIV;

static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

static void MarkEntity(Triggernometry.FFXIV.Entity entity, string markType)
{
    string markJson = $"{{\"ActorID\": 0x{entity.ID:X},\"MarkType\": \"{markType}\",\"LocalOnly\": false}}";
    RealPlugin.plug.InvokeNamedCallback("mark", markJson);
}

// 状态ID常量
const int STATUS_FREE_MAN = 4242;
const int STATUS_MONK = 4360;
const int STATUS_PROPHET = 4368;

// 只需计数的状态ID列表
var simpleCountStatuses = new[] { 4358, 4359, 4363, 4364, 4366, 4369, 4803, 4804, 4805 };

// 需要拼接名字的状态ID及其对应Builder
var nameBuilders = new Dictionary<int, StringBuilder>
{
    { STATUS_FREE_MAN, new StringBuilder() },
    { STATUS_MONK, new StringBuilder() },
    { STATUS_PROPHET, new StringBuilder() }
};

// 状态中文名映射
var statusNames = new Dictionary<int, string>
{
    { 4358, "骑士" }, { 4359, "狂战士" }, { 4361, "猎人" }, { 4362, "武士" },
    { 4363, "吟游诗人" }, { 4364, "风水师" }, { 4365, "时魔法师" }, { 4366, "炮击士" },
    { 4367, "药剂师" }, { 4369, "盗贼" },
    { 4803, "魔法剑士" }, { 4804, "剑斗士" }, { 4805, "舞者" }
};

// 计数器初始化
var counts = simpleCountStatuses.Concat(new[] { 4361, 4362, 4365, 4367 })
                               .ToDictionary(id => id, _ => 0);
int count4367NonHealer = 0;

// 初始化武士技能字典
var allBossSkillDict = new VariableDictionary();
for (int i = 1; i <= 4; i++)
{
    var bossDict = new VariableDictionary();
    bossDict.SetValue("扔钱", new VariableDictionary());
    bossDict.SetValue("居合", new VariableDictionary());
    allBossSkillDict.SetValue($"boss{i}", bossDict);
}

// 获取所有玩家实体
var allEntities = Triggernometry.FFXIV.Entity.GetEntities()
    .Where(e => e.BNpcID == 0 && e.Statuses != null)
    .ToList();

// 处理每个实体的状态
foreach (var entity in allEntities)
{
    foreach (var status in entity.Statuses)
    {
        int statusId = status.StatusID;
        
        // 拼接名字类型
        if (nameBuilders.TryGetValue(statusId, out var sb))
        {
            sb.Append(entity.Name).Append(",");
            continue;
        }
        
        // 简单计数类型
        if (simpleCountStatuses.Contains(statusId))
        {
            counts[statusId]++;
            continue;
        }
        
        // 特殊处理
        switch (statusId)
        {
            case 4361: // 猎人 - 标记stop
                counts[statusId]++;
                if (counts[statusId] <= 2)
                    MarkEntity(entity, $"stop{counts[statusId]}");
                break;
                
            case 4365: // 时魔法师 - 标记bind
                counts[statusId]++;
                if (counts[statusId] <= 3)
                    MarkEntity(entity, $"bind{counts[statusId]}");
                break;
                
            case 4367: // 药剂师 - 区分治疗/非治疗
                if (entity.Job?.IsHealer ?? false)
                {
                    counts[statusId]++;
                    if (counts[statusId] <= 8)
                        MarkEntity(entity, $"attack{counts[statusId]}");
                }
                else
                {
                    count4367NonHealer++;
                    if (count4367NonHealer <= 1)
                        MarkEntity(entity, "cross");
                }
                break;
                
            case 4362: // 武士 - 初始化技能字典
                counts[statusId]++;
                string samuraiKey = $"{entity.HexID}_{entity.Name}";
                for (int bossIdx = 1; bossIdx <= 4; bossIdx++)
                {
                    var bossDict = allBossSkillDict.GetValue($"boss{bossIdx}") as VariableDictionary;
                    (bossDict.GetValue("扔钱") as VariableDictionary).SetValue(samuraiKey, "0");
                    (bossDict.GetValue("居合") as VariableDictionary).SetValue(samuraiKey, "0");
                }
                break;
        }
    }
}

// 存储全局变量
allBossSkillDict.LastChanger = "Mata";
allBossSkillDict.LastChanged = DateTime.Now;
RealPlugin.Instance.GetVariableStore(true).Dict["The_Forked_Tower_Blood_all_boss_skills"] = allBossSkillDict;

// 生成输出
string GetNameOutput(int statusId, StringBuilder sb, string label)
{
    return sb.Length == 0 ? $"未发现辅助{label}" : $"辅助{label}是：{sb.ToString().TrimEnd(',')}";
}

var output = new StringBuilder()
    .AppendLine($"附近人数：{allEntities.Count}人")
    .AppendLine(GetNameOutput(STATUS_FREE_MAN, nameBuilders[STATUS_FREE_MAN], "自由人"))
    .AppendLine(GetNameOutput(STATUS_MONK, nameBuilders[STATUS_MONK], "武僧"))
    .AppendLine(GetNameOutput(STATUS_PROPHET, nameBuilders[STATUS_PROPHET], "预言师"))
    .AppendLine($"辅助盗贼{counts[4369]}人，辅助猎人{counts[4361]}人，辅助时魔法师{counts[4365]}人")
    .AppendLine($"辅助骑士{counts[4358]}人，辅助吟游诗人{counts[4363]}人，辅助武士{counts[4362]}人")
    .AppendLine($"辅助狂战士{counts[4359]}人，辅助风水师{counts[4364]}人，辅助炮击士{counts[4366]}人")
    .AppendLine($"辅助魔法剑士{counts[4803]}人，辅助剑斗士{counts[4804]}人，辅助舞者{counts[4805]}人")
    .AppendLine($"辅助药剂师{counts[4367] + count4367NonHealer}人（火种{count4367NonHealer}人）")
    .Append("武士技能计数字典已完成初始化")
    .ToString();

Log(output);

using System;
using System.Linq;
using System.Text;
using System.Threading;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.FFXIV;

const ushort TargetStatusID = 4354;
const double Y_TOLERANCE = 2.0;

static void Log(string message) => RealPlugin.plug.InvokeNamedCallback("command", $"/e [陨石检测] {message}");

static void DetectionLogic()
{
    try
    {
        string previousResult = "";
        int previousCount = 0;
        double previousTimer = 0;
        bool hasRecord = false;
        
        while (true)
        {
            var entities = Triggernometry.FFXIV.Entity.GetEntities()
                .Where(e => e.BNpcID == 0 && e.Statuses != null)
                .ToList();
            
            var targetEntities = entities
                .Where(e => e.Statuses.Any(s => s.StatusID == TargetStatusID))
                .ToList();
            
            if (!targetEntities.Any())
            {
                if (hasRecord)
                {
                    Log($"Buff已消失，消失前站位({previousTimer:F2}秒)：{previousResult}（共{previousCount}人）");
                }
                else
                {
                    Log("未检测到buff");
                }
                return;
            }
            
            var abnormalEntities = targetEntities
                .Where(e => Math.Abs(e.PosY - ${y}) > Y_TOLERANCE)
                .Select(e => $"{e.Name}(偏差{Math.Abs(e.PosY - ${y}):F2})")
                .ToList();
            
            previousResult = abnormalEntities.Any()
                ? "位置异常：" + string.Join(",", abnormalEntities)
                : "所有人位置正常";
            
            previousCount = targetEntities.Count;
            previousTimer = targetEntities
                .Select(e => e.Statuses.First(s => s.StatusID == TargetStatusID).Timer)
                .First();
            
            hasRecord = true;
            
            Thread.Sleep(10);
        }
    }
    catch (Exception ex)
    {
        Log($"检测错误：{ex.Message}");
    }
}

var thread = new Thread(DetectionLogic) { IsBackground = true };
thread.Start();

using System;
using System.Linq;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.FFXIV;

// 日志输出函数
static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

// 常量定义：与初始化逻辑保持一致
private const string GLOBAL_DICT_KEY = "The_Forked_Tower_Blood_all_boss_skills";
private const string TARGET_BOSS_KEY = "boss1";

// 关键修改：通过VariableStore获取全局变量（替代Interpreter.StaticHelpers）
VariableStore globalVarStore = RealPlugin.Instance.GetVariableStore(true); // true=全局变量

// 获取全局技能字典（与初始化时的字典结构匹配）
var allBossSkills = globalVarStore.GetDictVariable(GLOBAL_DICT_KEY); // 替代GetDictVariable(false, GLOBAL_DICT_KEY)
if (allBossSkills == null)
{
    Log("全局技能字典未初始化，无法重置");
    return;
}

// 获取boss4的子字典（对应初始化时的boss4层级，原逻辑不变）
var boss4Dict = allBossSkills.GetValue(TARGET_BOSS_KEY) as VariableDictionary;
if (boss4Dict == null)
{
    Log($"未找到{TARGET_BOSS_KEY}的字典，无法重置");
    return;
}

// 递归重置boss4字典中所有数值为0（包括嵌套的技能字典，原逻辑不变）
ResetNumericValues(boss4Dict);

// 关键修改：通过VariableStore保存更新后的全局字典（替代SetDictVariable）
globalVarStore.Dict[GLOBAL_DICT_KEY] = allBossSkills;
Log($"{TARGET_BOSS_KEY}字典中所有数值已重置为0");

// 递归处理方法：适配VariableDictionary结构（原逻辑不变）
static void ResetNumericValues(VariableDictionary dict)
{
    if (dict == null) return;
    
    // 遍历所有键（通过Values.Keys获取，符合VariableDictionary的结构）
    var keys = dict.Values.Keys.ToList();
    foreach (var key in keys)
    {
        var value = dict.GetValue(key);
        
        // 如果是子字典（如"扔钱"、"居合"技能的计数字典），递归处理
        if (value is VariableDictionary subDict)
        {
            ResetNumericValues(subDict);
        }
        // 如果是数值类型（初始化时存储为字符串形式的数字）
        else if (value is VariableScalar scalar)
        {
            // 验证是否为数字（与初始化时的存储方式匹配）
            if (int.TryParse(scalar.Value, out _) || 
                float.TryParse(scalar.Value, out _))
            {
                dict.SetValue(key, "0"); // 重置为0（保持字符串存储格式）
            }
        }
    }
}

using System;
using System.Linq;
using System.Text;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.Utilities;
using Triggernometry.FFXIV;

// 日志输出函数
static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

// 使用StringBuilder优化字符串拼接性能
var output = new StringBuilder();
var allEntities = Triggernometry.FFXIV.Entity.GetEntities().Where(e => e.BNpcID == 0);

// 读取食物buff（状态ID=48）剩余时间，小于300秒告警
foreach (var entity in allEntities)
{
    // 空值防护：避免实体为空导致的异常
    if (entity == null || entity.Statuses == null) continue;
    
    Status foodStatus = entity.Statuses.FirstOrDefault(s => s.StatusID == 48);
    if (foodStatus != null)
    {
        // 剩余时间小于300秒（5分钟）时记录
        if (foodStatus.Timer < 300)
        {
            output.Append(entity.Name).Append("(").Append((int)foodStatus.Timer).Append("秒),");
        }
    }
    else
    {
        // 无食物buff时显示0秒
        output.Append(entity.Name).Append("(0秒),");
    }
}

// 处理输出结果
string result;
if (output.Length == 0)
{
    result = "所有人都吃饭了";
}
else
{
    // 移除末尾的逗号
    result = "食物时间不够的是：" + output.ToString(0, output.Length - 1);
}

Log(result);

using System;
using System.Linq;
using System.Text;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.Utilities;
using Triggernometry.FFXIV;

// 日志输出函数（沿用你的可运行版本写法）
static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

// 使用StringBuilder优化字符串拼接（和你的食物检测代码保持一致）
var output = new StringBuilder();
var allEntities = Triggernometry.FFXIV.Entity.GetEntities().Where(e => e.BNpcID == 0);

// 核心逻辑：筛选带有4354状态（陨石）的玩家
foreach (var entity in allEntities)
{
    // 空值防护（和你的食物检测代码一致）
    if (entity == null || entity.Statuses == null) continue;
    
    // 检查是否有状态ID=4354的陨石状态
    Status cometStatus = entity.Statuses.FirstOrDefault(s => s.StatusID == 4354);
    if (cometStatus != null)
    {
        // 拼接玩家名称（保留核心逻辑）
        output.Append(entity.Name).Append(",");
    }
}

// 处理输出结果（沿用你的字符串处理逻辑）
string result;
if (output.Length == 0)
{
    result = "\n陨石在${var:The_Forked_Tower_Blood_boss1_comet}侧\n北侧分摊点：${lvar:The_Forked_Tower_Blood_boss1_comet_north[-1]}，${lvar:The_Forked_Tower_Blood_boss1_comet_north[-2]}\n南侧分摊点：${lvar:The_Forked_Tower_Blood_boss1_comet_south[-1]}，${lvar:The_Forked_Tower_Blood_boss1_comet_south[-2]}\n陨石点：无";
}
else
{
    // 移除末尾的逗号，拼接原始格式文本
    result = "\n陨石在${var:The_Forked_Tower_Blood_boss1_comet}侧\n北侧分摊点：${lvar:The_Forked_Tower_Blood_boss1_comet_north[-1]}，${lvar:The_Forked_Tower_Blood_boss1_comet_north[-2]}\n南侧分摊点：${lvar:The_Forked_Tower_Blood_boss1_comet_south[-1]}，${lvar:The_Forked_Tower_Blood_boss1_comet_south[-2]}\n陨石点：" + output.ToString(0, output.Length - 1);
}

// 执行日志输出
Log(result);

using System;
using System.Collections.Generic;
using System.Linq;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables; // 补充完整的变量命名空间（替换旧的Triggernometry.Variables）
using Triggernometry.PluginBridges;
using Triggernometry.FFXIV;

// ====================== 替代 Interpreter：通过 RealPlugin 获取全局 VariableStore ======================
// 1. 获取全局变量存储（true 表示获取全局变量，与原逻辑一致）
VariableStore globalVarStore = RealPlugin.Instance.GetVariableStore(true);

// 2. 替代 GetDictVariable：从全局 Dict 中获取目标字典（与原变量名保持一致）
var allBossSkills = globalVarStore.Dict["The_Forked_Tower_Blood_all_boss_skills"] as VariableDictionary;

if (allBossSkills == null)
{
    return;
}

// 获取当前触发的技能相关参数
string aid = $"${aid}"; // 技能ID
string sid = $"${sid}"; // 玩家ID
int currentCount = 0;

// 定义技能与BOSS的映射关系（根据实际情况调整）
var skillBossMap = new Dictionary<string, (string bossKey, string skillName)>
{
    {"A286", ("boss1", "扔钱")},  // A286对应boss1的扔钱技能
    {"A285", ("boss1", "居合")}   // A285对应boss1的居合技能
};

// 检查当前技能是否在监控列表中
if (skillBossMap.TryGetValue(aid, out var skillInfo))
{
    // 获取对应BOSS的技能字典
    var bossDict = allBossSkills.GetValue(skillInfo.bossKey) as VariableDictionary;
    if (bossDict == null)
    {
        return;
    }

    // 获取对应技能的玩家计数字典
    var skillDict = bossDict.GetValue(skillInfo.skillName) as VariableDictionary;
    if (skillDict == null)
    {
        return;
    }

    // 查找匹配的玩家并更新计数（使用初始化时的唯一键格式）
    var targetKey = skillDict.Values
        .Select(v => v.Key)
        .FirstOrDefault(key => key.StartsWith(sid));

    if (!string.IsNullOrEmpty(targetKey))
    {
        // 解析当前计数并加1
        if (int.TryParse(skillDict.GetStringValue(targetKey), out currentCount))
        {
            skillDict.SetValue(targetKey, (currentCount + 1).ToString());
            
            // 保存更新后的字典（层级赋值，与原逻辑一致）
            bossDict.SetValue(skillInfo.skillName, skillDict);
            allBossSkills.SetValue(skillInfo.bossKey, bossDict);
            
            // ====================== 替代 Interpreter：写入全局 Dict 变量 ======================
            // 3. 替代 SetDictVariable：更新全局变量（补充元数据，符合Triggernometry存储规范）
            allBossSkills.LastChanger = "Mata"; // 保持与初始化逻辑一致的修改者标识
            allBossSkills.LastChanged = DateTime.Now; // 更新修改时间
            globalVarStore.Dict["The_Forked_Tower_Blood_all_boss_skills"] = allBossSkills;
        }
    }
}

using System;
using System.Linq;
using System.Text;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.FFXIV;

// 日志输出函数（与可运行代码保持一致）
static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

// 常量定义：与初始化的全局字典保持一致
private const string GLOBAL_SKILL_DICT_KEY = "The_Forked_Tower_Blood_all_boss_skills";
private const string BOSS1_KEY = "boss1";
private const string SKILL_THROW_MONEY = "扔钱";
private const string SKILL_IAIJUTSU = "居合";

// 关键修改：参考可运行代码，通过VariableStore获取全局变量（替代Interpreter.StaticHelpers）
VariableStore globalVarStore = RealPlugin.Instance.GetVariableStore(true); // true=全局变量

// 获取全局技能字典及BOSS1的技能数据（替换原有Interpreter读取方式）
var allBossSkills = globalVarStore.GetDictVariable(GLOBAL_SKILL_DICT_KEY); // 替代GetDictVariable(false, GLOBAL_SKILL_DICT_KEY)
if (allBossSkills == null)
{
    return;
}

// 获取BOSS1的技能字典（遵循三层结构：全局→boss1→技能，原逻辑不变）
var boss1Dict = allBossSkills.GetValue(BOSS1_KEY) as VariableDictionary;
if (boss1Dict == null)
{
    return;
}

// 获取具体技能的计数字典（原逻辑不变）
var throwMoneyDict = boss1Dict.GetValue(SKILL_THROW_MONEY) as VariableDictionary;
var iaijutsuDict = boss1Dict.GetValue(SKILL_IAIJUTSU) as VariableDictionary;

if (throwMoneyDict == null || iaijutsuDict == null)
{
    return;
}

// 获取合格阈值（原逻辑不变）
int time1 = ${v:The_Forked_Tower_Blood_boss1_time1}; // 扔钱合格阈值
int time2 = ${v:The_Forked_Tower_Blood_boss1_time2}; // 居合合格阈值

// 使用StringBuilder优化字符串拼接（原逻辑不变）
var output1 = new StringBuilder();
var output2 = new StringBuilder();

// 检查扔钱技能合格情况（玩家键格式："HexID_名字"，原逻辑不变）
foreach (var item in throwMoneyDict.Values.OrderBy(kvp => kvp.Key))
{
    string playerKey = item.Key;
    // 从键中提取玩家名字（截取"HexID_"之后的部分）
    int nameStartIndex = playerKey.IndexOf('_') + 1;
    if (nameStartIndex <= 0 || nameStartIndex >= playerKey.Length)
        continue;
        
    string name = playerKey.Substring(nameStartIndex);
    
    // 解析计数并检查是否合格
    if (int.TryParse(item.Value?.ToString(), out int count) && count < time1)
    {
        output1.Append(name).Append($"({count}次),");
    }
}

// 检查居合技能合格情况（原逻辑不变）
foreach (var item in iaijutsuDict.Values.OrderBy(kvp => kvp.Key))
{
    string playerKey = item.Key;
    int nameStartIndex = playerKey.IndexOf('_') + 1;
    if (nameStartIndex <= 0 || nameStartIndex >= playerKey.Length)
        continue;
        
    string name = playerKey.Substring(nameStartIndex);
    
    if (int.TryParse(item.Value?.ToString(), out int count) && count < time2)
    {
        output2.Append(name).Append($"({count}次),");
    }
}

// 处理扔钱输出结果（原逻辑不变）
string result1 = output1.Length == 0 
    ? "boss1所有人扔钱都合格" 
    : "boss1扔钱不合格的是：" + output1.ToString(0, output1.Length - 1);

// 处理居合输出结果（原逻辑不变）
string result2 = output2.Length == 0 
    ? "boss1所有人居合都合格" 
    : "boss1居合不合格的是：" + output2.ToString(0, output2.Length - 1);

// 输出最终结果（原逻辑不变）
Log($"\n{result1}\n{result2}");

using System;
using System.Linq;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.FFXIV;

// 日志输出函数（与可运行模板保持一致，简化命名空间限定）
static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

// 常量定义：与初始化逻辑保持一致
private const string GLOBAL_DICT_KEY = "The_Forked_Tower_Blood_all_boss_skills";
private const string TARGET_BOSS_KEY = "boss4";

// 关键修改：通过VariableStore获取全局变量（替代Interpreter.StaticHelpers）
VariableStore globalVarStore = RealPlugin.Instance.GetVariableStore(true); // true=全局变量

// 获取全局技能字典（与初始化时的字典结构匹配，替换原有Interpreter读取方式）
var allBossSkills = globalVarStore.GetDictVariable(GLOBAL_DICT_KEY);
if (allBossSkills == null)
{
    Log("全局技能字典未初始化，无法重置");
    return;
}

// 获取boss4的子字典（对应TARGET_BOSS_KEY，原逻辑不变）
var boss4Dict = allBossSkills.GetValue(TARGET_BOSS_KEY) as VariableDictionary;
if (boss4Dict == null)
{
    Log($"未找到{TARGET_BOSS_KEY}的字典，无法重置");
    return;
}

// 递归重置boss4字典中所有数值为0（包括嵌套的技能字典）
ResetNumericValues(boss4Dict);

// 关键修改：通过VariableStore保存更新后的全局字典（替代SetDictVariable）
globalVarStore.Dict[GLOBAL_DICT_KEY] = allBossSkills;
Log($"{TARGET_BOSS_KEY}字典中所有数值已重置为0");

// 递归处理方法：适配VariableDictionary结构（原逻辑不变）
static void ResetNumericValues(VariableDictionary dict)
{
    if (dict == null) return;
    
    // 遍历所有键（通过Values.Keys获取，符合VariableDictionary的结构）
    var keys = dict.Values.Keys.ToList();
    foreach (var key in keys)
    {
        var value = dict.GetValue(key);
        
        // 如果是子字典（如"扔钱"、"居合"技能的计数字典），递归处理
        if (value is VariableDictionary subDict)
        {
            ResetNumericValues(subDict);
        }
        // 如果是数值类型（初始化时存储为字符串形式的数字）
        else if (value is VariableScalar scalar)
        {
            // 验证是否为数字（与初始化时的存储方式匹配）
            if (int.TryParse(scalar.Value, out _) || 
                float.TryParse(scalar.Value, out _))
            {
                dict.SetValue(key, "0"); // 重置为0（保持字符串存储格式）
            }
        }
    }
}

using System;
using System.Linq;
using System.Text;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.Utilities;
using Triggernometry.FFXIV;

// 日志输出函数
static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

// 使用StringBuilder优化字符串拼接性能
var output = new StringBuilder();
var allEntities = Triggernometry.FFXIV.Entity.GetEntities().Where(e => e.BNpcID == 0);

// 读取食物buff（状态ID=48）剩余时间，小于300秒告警
foreach (var entity in allEntities)
{
    // 空值防护：避免实体为空导致的异常
    if (entity == null || entity.Statuses == null) continue;
    
    Status foodStatus = entity.Statuses.FirstOrDefault(s => s.StatusID == 48);
    if (foodStatus != null)
    {
        // 剩余时间小于300秒（5分钟）时记录
        if (foodStatus.Timer < 300)
        {
            output.Append(entity.Name).Append("(").Append((int)foodStatus.Timer).Append("秒),");
        }
    }
    else
    {
        // 无食物buff时显示0秒
        output.Append(entity.Name).Append("(0秒),");
    }
}

// 处理输出结果
string result;
if (output.Length == 0)
{
    result = "所有人都吃饭了";
}
else
{
    // 移除末尾的逗号
    result = "食物时间不够的是：" + output.ToString(0, output.Length - 1);
}

Log(result);

